  "misconception": {
    "pack_id": null,
    "wrong": "Любая тёмная полоса или неровность на имидже — трещина, а значит, признак нефти.",
    "right": "Трещины и вывалы — разные объекты. Вывал — разрушение стенки от напряжения, его направление задаёт минимальное горизонтальное напряжение.",
    "claims": ["c1", "c4", "c5"]
  },
  "data_meaning": {
    "inputs": [
      {"text": "Изображение стенки ствола в масштабе сантиметров, полученное имиджем.", "claims": ["c6"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Признаки на картинке: трещины, мелкие слои, вывалы. Для тонких пластов — оценка эффективной толщины.", "claims": ["c1"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Вывал определяется условием «напряжение больше прочности». Сам по себе вывал не даёт величину напряжений.", "claims": ["c5"], "hypothesis": true},
      {"text": "Книга не задаёт порогов размера трещины или слоя.", "claims": [], "hypothesis": false}
    ]
  },
  "it_analogy": {
    "pack_id": "IT01",
    "analogy": "Имидж — как тепловая карта откликов датчиков по поверхности: каждая точка даёт отклик, вместе они дают картину.",
    "breaks_where": "Тепловая карта показывает состояние системы. Вывал — реальное разрушение стенки, а не ошибка отображения, и логами его не откатить."
  },
  "now_nuance": null,
  "threshold": {
    "is_threshold": true,
    "why": "Вывал описывает напряжение вокруг ствола, а не состав породы. Без этого различия неровности на имидже читают как геологию."
  },
